        # Mock the internal methods to capture execution path without side effects
        package._clone_repository = MagicMock(return_value="cloned")
        package._pull_repository = MagicMock(return_value="pulled")

        # Ensure the target directory does not exist
        self.assertFalse(package.clone_directory.exists())

        # Act
        result = package.lazy_clone()

        # Assert
        self.assertEqual(result, "cloned")
        package._clone_repository.assert_called_once()
        package._pull_repository.assert_not_called()

