from pylint.config._pylint_config.exceptions import InvalidUserInput

class TestGetAndValidateFormat(unittest.TestCase):

    @patch("builtins.input", side_effect=["t"])
    def test_get_and_validate_format_toml_t(self, mock_input):
        result = get_and_validate_format()
        self.assertEqual(result, "toml")

    @patch("builtins.input", side_effect=["T"])
    def test_get_and_validate_format_toml_uppercase_t(self, mock_input):
        result = get_and_validate_format()
        self.assertEqual(result, "toml")

    @patch("builtins.input", side_effect=["toml"])
    def test_get_and_validate_format_toml_full_string(self, mock_input):
        result = get_and_validate_format()
        self.assertEqual(result, "toml")

    @patch("builtins.input", side_effect=["TOML"])
    def test_get_and_validate_format_toml_full_uppercase(self, mock_input):
        result = get_and_validate_format()
        self.assertEqual(result, "toml")

    @patch("builtins.input", side_effect=["i"])
    def test_get_and_validate_format_ini_i(self, mock_input):
        result = get_and_validate_format()
        self.assertEqual(result, "ini")

    @patch("builtins.input", side_effect=["I"])
    def test_get_and_validate_format_ini_uppercase_i(self, mock_input):
        result = get_and_validate_format()
        self.assertEqual(result, "ini")

    @patch("builtins.input", side_effect=["ini"])
    def test_get_and_validate_format_ini_full_string(self, mock_input):
        result = get_and_validate_format()
        self.assertEqual(result, "ini")

    @patch("builtins.input", side_effect=["INI"])
    def test_get_and_validate_format_ini_full_uppercase(self, mock_input):
        result = get_and_validate_format()
        self.assertEqual(result, "ini")

    @patch("builtins.input", side_effect=["cfg"])
    def test_get_and_validate_format_cfg(self, mock_input):
        # cfg starts with 'c', which does not start with 't', so it falls back to ini
        # Assuming SUPPORTED_FORMATS includes 'cfg' or the logic handles it as 'ini' if supported.
        # Based on the function code: if format_type.startswith("t"): return "toml"; return "ini".
        # This implies anything not starting with 't' returns 'ini', provided it is in SUPPORTED_FORMATS.
        result = get_and_validate_format()
        self.assertEqual(result, "ini")

    @patch("builtins.input", side_effect=["invalid"])
    def test_get_and_validate_format_invalid(self, mock_input):
        with self.assertRaises(InvalidUserInput) as context:
            get_and_validate_format()
        self.assertIn("invalid", str(context.exception))

    @patch("builtins.input", side_effect=["123"])
    def test_get_and_validate_format_numeric(self, mock_input):
        with self.assertRaises(InvalidUserInput) as context:
            get_and_validate_format()
        self.assertIn("123", str(context.exception))

    @patch("builtins.input", side_effect=[""])
    def test_get_and_validate_format_empty(self, mock_input):
        with self.assertRaises(InvalidUserInput) as context:
            get_and_validate_format()
        self.assertIn("", str(context.exception))

    @patch("builtins.input", side_effect=["  t  "])
    def test_get_and_validate_format_toml_with_whitespace(self, mock_input):
        result = get_and_validate_format()
        # The function calls .lower() on the input. "  t  ".lower() is "  t  ".
        # "  t  " starts with " ", not "t". However, typical implementation might strip.
        # Looking at the provided code, there is no strip().
        # "  t  ".startswith("t") is False.
        # If SUPPORTED_FORMATS contains "  t  " (unlikely) it raises InvalidUserInput.
        # If not, it raises InvalidUserInput.
        # However, usually utils strip. Let's assume strict adherence to provided code.
        with self.assertRaises(InvalidUserInput):
            get_and_validate_format()

    @patch("builtins.input", side_effect=["json"])
    def test_get_and_validate_format_unsupported_format(self, mock_input):
        with self.assertRaises(InvalidUserInput) as context:
            get_and_validate_format()
        self.assertIn("json", str(context.exception))

