import unittest

from pylint.graph import get_cycles


class TestGetCycles(unittest.TestCase):
    def test_empty_graph(self) -> None:
        graph = {}
        result = get_cycles(graph)
        self.assertEqual(result, ())

    def test_graph_no_cycles(self) -> None:
        graph = {
            "A": {"B"},
            "B": {"C"},
            "C": set(),
        }
        result = get_cycles(graph)
        self.assertEqual(result, [])

    def test_self_loop(self) -> None:
        graph = {
            "A": {"A"},
            "B": {"C"},
        }
        result = get_cycles(graph)
        self.assertEqual(len(result), 1)
        self.assertIn(["A"], result)

    def test_simple_cycle(self) -> None:
        graph = {
            "A": {"B"},
            "B": {"C"},
            "C": {"A"},
        }
        result = get_cycles(graph)
        self.assertEqual(len(result), 1)
        self.assertEqual(result[0], ["A", "B", "C", "A"])

    def test_disconnected_components_with_cycles(self) -> None:
        graph = {
            "A": {"B"},
            "B": {"A"},
            "C": {"D"},
            "D": {"C"},
        }
        result = get_cycles(graph)
        self.assertEqual(len(result), 2)
        # Order of cycles is not guaranteed by the implementation, 
        # but checking for presence is safe.
        cycles_found = [tuple(c) for c in result]
        self.assertIn(("A", "B", "A"), cycles_found)
        self.assertIn(("C", "D", "C"), cycles_found)

    def test_complex_branching(self) -> None:
        graph = {
            "A": {"B", "C"},
            "B": {"D"},
            "C": {"D"},
            "D": {"E"},
            "E": set(),
        }
        result = get_cycles(graph)
        self.assertEqual(result, [])

    def test_cycle_in_subgraph(self) -> None:
        graph = {
            "A": {"B", "C"},
            "B": {"D"},
            "C": {"D"},
            "D": {"B"}, # B <-> D cycle
        }
        result = get_cycles(graph)
        # We expect a cycle B -> D -> B
        # It might be reported twice if starting from B and D, 
        # or once depending on deduplication logic in internal helper.
        # But we assert at least one is found.
        self.assertTrue(len(result) >= 1)
        self.assertTrue(any(c in [["B", "D", "B"], ["D", "B", "D"]] for c in result))

    def test_with_vertices_subset(self) -> None:
        graph = {
            "A": {"B"},
            "B": {"A"},
            "C": {"D"},
            "D": {"C"},
        }
        # Restrict search to only A and B
        vertices = ["A", "B"]
        result = get_cycles(graph, vertices)
        self.assertEqual(len(result), 1)
        self.assertEqual(result[0], ["A", "B", "A"])

    def test_with_vertices_subset_no_cycle_in_subset(self) -> None:
